export const KETTLEBELL_PATTERNS: Record<PadraoKettlebell, { nome: string; icone: string; cor: string; descricao: string }> = {
  HINGE: { nome: 'Hinge', icone: '🔄', cor: 'rose', descricao: 'Balístico de quadril — potência posterior (glúteos, isquiotibiais)' },
  SQUAT: { nome: 'Squat', icone: '🦵', cor: 'emerald', descricao: 'Agachamento + variações — quadríceps, mobilidade' },
  PRESS: { nome: 'Press', icone: '⬆️', cor: 'amber', descricao: 'Empurrar vertical/horizontal — ombros, peito' },
  PULL: { nome: 'Pull', icone: '↔️', cor: 'cyan', descricao: 'Puxar — costas, bíceps, postura' },
  CARRY: { nome: 'Carry', icone: '🚶', cor: 'orange', descricao: 'Caminhada com carga — grip, core, postura' },
  ROT: { nome: 'Rotação', icone: '🌪️', cor: 'purple', descricao: 'Rotação + estabilidade multi-planar — core, ombros' },
  COND: { nome: 'Condicionamento', icone: '🔥', cor: 'red', descricao: 'Cardio + potência — metabolic conditioning' },
  FLOW: { nome: 'Flow', icone: '🌊', cor: 'blue', descricao: 'Sequências encadeadas — coordenação, controle' },
};

export function getKettlebellByPadrao(padrao: PadraoKettlebell): ExercicioKettlebell[] {
  return KETTLEBELL_EXERCICIOS.filter((ex) => ex.padraoKb === padrao);
}

export function getKettlebellByGrupo(grupo: string): ExercicioKettlebell[] {
  return KETTLEBELL_EXERCICIOS.filter((ex) => ex.grupo === grupo);
}

export function getKettlebellByNivel(nivel: 'iniciante' | 'intermediario' | 'avancado'): ExercicioKettlebell[] {
  return KETTLEBELL_EXERCICIOS.filter((ex) => ex.nivel === nivel);
}

/**
 * Retorna a "dica muscular curta" do exercício - 1 frase resumindo ONDE sentir.
 * Útil para mostrar em qualquer ponto onde o exercício é citado (listas, badges, tabs).
 */
export function getDicaMuscularCurta(id: string): string | null {
  const ex = KETTLEBELL_EXERCICIOS.find((e) => e.id === id);
  if (!ex?.sensacaoPrincipal) return null;
  return ex.sensacaoPrincipal;
}

/**
 * Retorna o erro muscular curto - 1 frase do que acontece se fizer errado.
 */
export function getErroMuscularCurto(id: string): string | null {
  const ex = KETTLEBELL_EXERCICIOS.find((e) => e.id === id);
  if (!ex?.erroMuscular) return null;
  return ex.erroMuscular;
}

/**
 * Retorna a primeira sensação do mapa muscular (a principal).
 */
export function getPrincipalMusculatura(id: string): string | null {
  const ex = KETTLEBELL_EXERCICIOS.find((e) => e.id === id);
  return ex?.mapaMuscularLeigo?.[0] ?? null;
}

/**
 * Retorna os primeiros N itens do mapa muscular (para mostrar em cards/listas).
 */
export function getTopMusculaturas(id: string, n = 3): string[] {
  const ex = KETTLEBELL_EXERCICIOS.find((e) => e.id === id);
  if (!ex?.mapaMuscularLeigo) return [];
  return ex.mapaMuscularLeigo.slice(0, n);
}

